class DataTableExample extends StatefulWidget {
  @override
  State<DataTableExample> createState() => _DataTableExampleState();
}

class _DataTableExampleState extends State<DataTableExample> {
  late List<Map<String, dynamic>> _rows;
  String _sortColumnKey = 'name';
  bool _sortAscending = true;
  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    _loadData();
  }

  void _loadData() {
    // Load and filter data
    _rows = [
      {'id': '1', 'name': 'John', 'email': 'john@example.com', 'status': 'Active'},
      {'id': '2', 'name': 'Jane', 'email': 'jane@example.com', 'status': 'Pending'},
    ];
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    return CKDataTable(
      columns: [
        CKTableColumn(title: 'Name', key: 'name', type: ColumnType.text),
        CKTableColumn(title: 'Email', key: 'email', type: ColumnType.text),
        CKTableColumn(title: 'Status', key: 'status', type: ColumnType.badge),
      ],
      rows: _rows,
      sortColumnKey: _sortColumnKey,
      sortAscending: _sortAscending,
      onSortChanged: (key, ascending) {
        setState(() {
          _sortColumnKey = key;
          _sortAscending = ascending;
          _loadData();
        });
      },
      searchQuery: _searchQuery,
      onSearchChanged: (query) {
        setState(() => _searchQuery = query);
        _loadData();
      },
      selectionMode: TableSelectionMode.multiple,
    );
  }
}

