class ResponsiveGrid extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final isMobile = MediaQuery.of(context).size.width < context.ckBreakpoints.md;
    final isTablet = MediaQuery.of(context).size.width < context.ckBreakpoints.lg;

    final columns = isMobile ? 1 : isTablet ? 2 : 3;

    return GridView.count(
      crossAxisCount: columns,
      mainAxisSpacing: context.ckSpacing.lg,
      crossAxisSpacing: context.ckSpacing.lg,
      children: List.generate(12, (i) => CKCard(title: 'Item $i')),
    );
  }
}

